def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return min(budget, 18.0)

    slots = int(supply // WATER_REQ)
    if slots < 0:
        slots = 0

    prev_bids = []
    affordable_prev_bids = []
    rich_count = 0
    urgent_opp = 0
    max_affordable_enemy = 0.0

    for oid, opp in alive:
        obudget = opp.get('budget', 0.0)
        if obudget >= 80:
            rich_count += 1
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            affordable_prev_bids.append(min(float(bid), float(obudget)))
            if min(float(bid), float(obudget)) > max_affordable_enemy:
                max_affordable_enemy = min(float(bid), float(obudget))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1
    if no_water >= 2:
        danger += 3
    elif no_water >= 1:
        danger += 2

    if slots >= 2:
        if danger >= 3:
            target = max(58.0, avg_prev + 2.0)
        else:
            target = max(42.0, avg_prev * 0.72)
        if rich_count >= 2:
            target += 6.0
        return max(0.0, min(budget, target))

    if danger >= 5:
        target = max(96.0, max_affordable_enemy + 2.5)
        if urgent_opp >= 2:
            target += 6.0
        return max(0.0, min(budget, target))

    if danger >= 3:
        target = max(78.0, max_affordable_enemy + 1.5)
        return max(0.0, min(budget, target))

    if budget < 90:
        return max(0.0, min(budget, 12.0))

    if highest_prev >= 110 or rich_count >= 2:
        return max(0.0, min(budget, 16.0))

    if supply >= 24 and highest_prev < 90:
        return max(0.0, min(budget, 51.0))

    return max(0.0, min(budget, 22.0))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = int(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bid pressure from traces
    prev_bids = []
    prev_hp_after = []
    for opp_id, opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid', 0.0)))
            except Exception:
                pass
            try:
                prev_hp_after.append(int(prev.get('hp_after', 0)))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    lowest_prev_bid = min(prev_bids) if prev_bids else 0.0

    # Identify likely low-pressure opponents: those who ended yesterday with very low budget or very low hp_after
    low_pressure = 0
    for opp_id, opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if not prev:
            continue
        bid = prev.get('bid', None)
        hp_after = prev.get('hp_after', None)
        budget_after = prev.get('budget_after', None)
        alive_now = opponents_status[opp_id].get('alive', False)
        if not alive_now:
            continue
        try:
            bafter = float(budget_after)
        except Exception:
            bafter = None
        try:
            hpa = int(hp_after) if hp_after is not None else None
        except Exception:
            hpa = None
        try:
            bidf = float(bid) if bid is not None else None
        except Exception:
            bidf = None

        if bidf is not None and bidf <= DAILY_SALARY * 0.25:
            low_pressure += 1
        elif bafter is not None and bafter <= 0.0:
            low_pressure += 1
        elif hpa is not None and hpa <= 1:
            low_pressure += 1

    # Supply pressure: higher supply means competition is less fierce; lower supply means we should secure water.
    # Convert supply to a normalized [0,1] pressure.
    if MAX_SUPPLY == MIN_SUPPLY:
        supply_pressure = 0.5
    else:
        supply_pressure = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    supply_pressure = max(0.0, min(1.0, supply_pressure))

    # Our urgency: if no_water_days is high or hp is low, bid more.
    urgency = 0.0
    if no_water_days >= 2:
        urgency += 0.35
    if no_water_days >= 3:
        urgency += 0.25
    if hp <= 2:
        urgency += 0.45
    elif hp <= 3:
        urgency += 0.25
    else:
        urgency += 0.10

    # Base bid target: aim to beat low underbidders without matching high survivors.
    # Use yesterday highest as a ceiling signal; but we undercut by targeting a fraction.
    # If yesterday highest was very high, assume Cindy/Alex are competitive.
    if highest_prev_bid >= DAILY_SALARY * 1.8:
        # High bidders present; be selective.
        target = DAILY_SALARY * (0.55 + 0.25 * urgency) + supply_pressure * DAILY_SALARY * 0.15
        # If we are in danger, push closer to highest_prev_bid but still avoid full match.
        if hp <= 2 or no_water_days >= 3:
            target = min(highest_prev_bid * 0.92, target + DAILY_SALARY * 0.25)
        else:
            target = min(highest_prev_bid * 0.75, target)
    else:
        # Overall bids were lower; we can be more aggressive to secure.
        target = DAILY_SALARY * (0.6 + 0.35 * urgency) + supply_pressure * DAILY_SALARY * 0.2
        # If many low-pressure opponents, we can bid closer to lower end.
        if low_pressure >= 2:
            target = DAILY_SALARY * (0.5 + 0.25 * urgency) + supply_pressure * DAILY_SALARY * 0.12

    # Add a small increment over the lowest observed bid if it's meaningful.
    if lowest_prev_bid > 0:
        target = max(target, lowest_prev_bid + 1.5)

    # Cap by budget and also by a reasonable maximum to avoid bankruptcy.
    # If our budget is low, bid what we can.
    max_reasonable = max(0.0, min(budget, DAILY_SALARY * (1.2 + 0.6 * urgency)))
    bid = max(0.0, min(max_reasonable, target))

    # If our budget is extremely low, still try to get water when urgent.
    if budget <= DAILY_SALARY * 0.35:
        if hp <= 2 or no_water_days >= 3:
            bid = max(0.0, min(budget, DAILY_SALARY * 0.95))
        else:
            bid = max(0.0, min(budget, DAILY_SALARY * 0.5))

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # Emergency Bidding: If HP is very low or I've missed water
    if my_hp <= 2 or my_no_water_days >= 1:
        # Bid aggressively to ensure survival. Add a bonus based on no_water_days.
        return min(my_budget, DAILY_SALARY * 0.95 + (my_no_water_days * 10))

    # If no active opponents, or it's day 1 (no previous trace for opponents)
    if not alive_opponents or day_context['day'] == 1:
        # Default strong bid to establish presence or if competition is unknown.
        return min(my_budget, DAILY_SALARY * 0.75)

    # Collect yesterday's bids from active opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # If for some reason no yesterday bids were collected, fall back to default.
    if not yesterday_bids:
        return min(my_budget, DAILY_SALARY * 0.7)

    highest_prev_bid = max(yesterday_bids)
    average_prev_bid = sum(yesterday_bids) / len(yesterday_bids)

    # --- Dynamic Bidding Logic based on opponent's previous behavior ---

    # If highest previous bid was very high, it indicates strong competition.
    if highest_prev_bid >= DAILY_SALARY * 0.9:
        # If my HP is good, I can try to be slightly strategic, maybe match or slightly undercut.
        if my_hp > 5:
            # Bid slightly above average, but not necessarily highest, to save budget.
            return min(my_budget, max(DAILY_SALARY * 0.75, average_prev_bid + 5))
        else:
            # If my HP is moderate, I still need water, so bid to win.
            return min(my_budget, highest_prev_bid + 5)

    # If highest previous bid was moderate
    elif highest_prev_bid >= DAILY_SALARY * 0.6:
        # Bid slightly above the highest to secure water, but don't overspend.
        return min(my_budget, highest_prev_bid + 2)

    # If highest previous bid was low
    else:
        # Opponents are not bidding aggressively. Try to save budget.
        # Bid slightly above their highest low bid, but ensure it's a reasonable amount for water.
        return min(my_budget, max(DAILY_SALARY * 0.6, highest_prev_bid + 1))

    # Fallback (should ideally not be reached)
    return min(my_budget, DAILY_SALARY * 0.7)
